def slugify(s):
    s = s.lower()
    # Decompose unicode and strip combining marks (e.g. õ -> o)
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    # Replace any non-alphanumeric character with a hyphen,
    # then collapse runs and strip leading/trailing hyphens.
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    parts = [p for p in ''.join(out).split('-') if p]
    return '-'.join(parts)

import unicodedata


def slugify(s):
    s = s.lower()
    s = unicodedata.normalize('NFKD', s)
    out = []
    for ch in s:
        if unicodedata.category(ch).startswith('M'):
            continue
        if ch.isalnum():
            out.append(ch)
        else:
            out.append('-')
    # Collapse consecutive dashes
    result = []
    for ch in out:
        if ch == '-' and result and result[-1] == '-':
            continue
        result.append(ch)
    return ''.join(result).strip('-')
